    H.ops.workUpdate,
    H.ops.workCancel,
    H.ops.attemptsRecover,
    H.ops.resolve(ownerDecision),
    H.ops.memoryRead,
    H.ops.memoryWrite,
    H.ops.telemetryRead,
    H.ops.accountsRead,
    H.ops.accountsShare,
    H.operation('production-health-probe', productionHealthProbe),
